module tb;
    reg [7:0] a;
    reg [7:0] b;
    wire [7:0] s;
    wire overflow;

    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;

    // Task to check expected vs actual outputs using 4-state case inequality
    task check_result;
        input [7:0] exp_s;
        input exp_ovf;
        begin
            #1; // Allow combinational propagation
            if (s !== exp_s || overflow !== exp_ovf) begin
                $display("ERROR: a=%d, b=%d | Got s=%d (exp %d), overflow=%b (exp %b)", 
                         $signed(a), $signed(b), $signed(s), $signed(exp_s), overflow, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // 1. Positive + Positive without overflow
        a = 8'sd10; b = 8'sd20; check_result(8'sd30, 1'b0);

        // 2. Positive + Positive WITH overflow (Max positive + 1)
        a = 8'sd127; b = 8'sd1; check_result(8'h80, 1'b1);

        // 3. Negative + Negative without overflow
        a = -8'sd10; b = -8'sd20; check_result(-8'sd30, 1'b0);

        // 4. Negative + Negative WITH overflow (Max negative + -1)
        a = -8'sd128; b = -8'sd1; check_result(8'h7F, 1'b1);

        // 5. Positive + Negative (Never overflows in 2's complement)
        a = 8'sd50; b = -8'sd50; check_result(8'sd0, 1'b0);

        // 6. Edge case: Zero addition
        a = 8'sd0; b = 8'sd0; check_result(8'sd0, 1'b0);

        // 7. Edge case: -128 + 127
        a = -8'sd128; b = 8'sd127; check_result(-8'sd1, 1'b0);

        // 8. Systematic bounded sweep of interesting boundary values
        // Testing extreme corners of 8-bit signed range: {-128, -1, 0, 1, 127}
        begin
            reg signed [7:0] test_vals [0:4];
            integer i, j;
            test_vals[0] = -128;
            test_vals[1] = -1;
            test_vals[2] = 0;
            test_vals[3] = 1;
            test_vals[4] = 127;

            for (i = 0; i < 5; i = i + 1) begin
                for (j = 0; j < 5; j = j + 1) begin
                    reg signed [8:0] ref_sum;
                    reg ref_ovf;

                    a = test_vals[i];
                    b = test_vals[j];

                    ref_sum = $signed(test_vals[i]) + $signed(test_vals[j]);
                    ref_ovf = (ref_sum[8] !== ref_sum[7]);

                    check_result(ref_sum[7:0], ref_ovf);
                end
            end
        end

        // Final Result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
